  Verse(
    id: 530,
    verseKey: '4:37',
    text:
        'ٱلَّذِينَ يَ&lt;tajweed class=qalaqah&gt;بْ&lt;/tajweed&gt;خَلُونَ وَيَأْمُرُونَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;&lt;tajweed class=laam_shamsiyah&gt;ل&lt;/tajweed&gt;&lt;tajweed class=ghunnah&gt;نّ&lt;/tajweed&gt;َاسَ بِ&lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْبُخْلِ وَيَكْتُمُونَ م&lt;tajweed class=madda_obligatory&gt;َآ&lt;/tajweed&gt; ءَاتَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;هُمُ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ مِ&lt;tajweed class=ikhafa&gt;ن ف&lt;/tajweed&gt;َضْلِه&lt;tajweed class=madda_normal&gt;ِۦ&lt;/tajweed&gt;‌ۗ وَأَعْتَ&lt;tajweed class=qalaqah&gt;دْ&lt;/tajweed&gt;نَا لِلْكَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;فِرِينَ عَذَا&lt;tajweed class=idgham_ghunnah&gt;بًا م&lt;/tajweed&gt;ُّهِينًا &lt;span class=end&gt;٣٧&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 84,
    juzNumber: 5,
  ),
  Verse(
    id: 531,
    verseKey: '4:38',
    text:
        'وَ&lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لَّذِينَ يُ&lt;tajweed class=ikhafa&gt;نف&lt;/tajweed&gt;ِقُونَ أَمْو&lt;tajweed class=madda_normal&gt;َٲ&lt;/tajweed&gt;لَهُمْ رِئ&lt;tajweed class=madda_obligatory&gt;َا&lt;/tajweed&gt;ٓءَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;&lt;tajweed class=laam_shamsiyah&gt;ل&lt;/tajweed&gt;&lt;tajweed class=ghunnah&gt;نّ&lt;/tajweed&gt;َاسِ وَلَا يُؤْمِنُونَ بِ&lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهِ وَلَا بِ&lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْيَوْمِ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْأَخِرِ‌ۗ وَم&lt;tajweed class=idgham_ghunnah&gt;َن ي&lt;/tajweed&gt;َكُنِ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;&lt;tajweed class=laam_shamsiyah&gt;ل&lt;/tajweed&gt;شَّيْطَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;نُ لَهُ&lt;tajweed class=madda_normal&gt;ۥ&lt;/tajweed&gt; قَرِي&lt;tajweed class=ikhafa&gt;نًا ف&lt;/tajweed&gt;َس&lt;tajweed class=madda_obligatory&gt;َا&lt;/tajweed&gt;ٓءَ قَرِينًا &lt;span class=end&gt;٣٨&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 85,
    juzNumber: 5,
  ),
  Verse(
    id: 532,
    verseKey: '4:39',
    text:
        'وَمَاذَا عَلَيْهِمْ لَوْ ءَامَنُو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; بِ&lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهِ وَ&lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْيَوْمِ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْأَخِرِ وَأَ&lt;tajweed class=ikhafa&gt;نف&lt;/tajweed&gt;َقُو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; مِ&lt;tajweed class=ghunnah&gt;مّ&lt;/tajweed&gt;َا رَزَقَهُمُ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ‌ۚ وَكَانَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ بِهِمْ عَلِيمًا &lt;span class=end&gt;٣٩&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 85,
    juzNumber: 5,
  ),
  Verse(
    id: 533,
    verseKey: '4:40',
    text:
        'إِ&lt;tajweed class=ghunnah&gt;نّ&lt;/tajweed&gt;َ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّ&lt;tajweed class=idgham_ghunnah&gt;ةٍ‌ۖ و&lt;/tajweed&gt;َإِ&lt;tajweed class=ikhafa&gt;ن ت&lt;/tajweed&gt;َكُ حَسَنَ&lt;tajweed class=idgham_ghunnah&gt;ةً ي&lt;/tajweed&gt;ُضَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;عِفْهَا وَيُؤْتِ م&lt;tajweed class=idgham_wo_ghunnah&gt;ِن ل&lt;/tajweed&gt;َّدُنْهُ أَ&lt;tajweed class=qalaqah&gt;جْ&lt;/tajweed&gt;رًا عَظِيمًا &lt;span class=end&gt;٤٠&lt;/span&gt;',
