  Verse(
    id: 576,
    verseKey: '4:83',
    text:
        'وَإِذَا ج&lt;tajweed class=madda_obligatory&gt;َا&lt;/tajweed&gt;ٓءَهُمْ أَمْ&lt;tajweed class=idgham_ghunnah&gt;رٌ م&lt;/tajweed&gt;ِّنَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْأَمْنِ أَوِ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْخَوْفِ أَذَاعُو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; بِه&lt;tajweed class=madda_normal&gt;ِۦ&lt;/tajweed&gt;‌ۖ وَلَوْ رَدُّوهُ إِلَى &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;&lt;tajweed class=laam_shamsiyah&gt;ل&lt;/tajweed&gt;رَّسُولِ وَإِلَ&lt;tajweed class=madda_obligatory&gt;ىٰٓ&lt;/tajweed&gt; أُ&lt;tajweed class=slnt&gt;وْ&lt;/tajweed&gt;لِى &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْأَمْرِ مِنْهُمْ لَعَلِمَهُ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لَّذِينَ يَسْتَ&lt;tajweed class=iqlab&gt;نۢب&lt;/tajweed&gt;ِطُونَهُ&lt;tajweed class=madda_normal&gt;ۥ&lt;/tajweed&gt; مِنْهُمْ‌ۗ وَلَوْلَا فَضْلُ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهِ عَلَيْكُمْ وَرَحْمَتُهُ&lt;tajweed class=madda_normal&gt;ۥ&lt;/tajweed&gt; لَ&lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;تَّبَعْتُمُ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;&lt;tajweed class=laam_shamsiyah&gt;ل&lt;/tajweed&gt;شَّيْطَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;نَ إِلَّا قَلِيلاً &lt;span class=end&gt;٨٣&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 91,
    juzNumber: 5,
  ),
  Verse(
    id: 577,
    verseKey: '4:84',
    text:
        'فَقَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;تِلْ فِى سَبِيلِ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ‌ۚ وَحَرِّضِ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْمُؤْمِنِينَ‌ۖ عَسَى &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ أ&lt;tajweed class=idgham_ghunnah&gt;َن ي&lt;/tajweed&gt;َكُفَّ بَأْسَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لَّذِينَ كَفَرُو&lt;tajweed class=slnt&gt;اْ‌ۚ&lt;/tajweed&gt; وَ&lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ أَشَدُّ بَأْ&lt;tajweed class=idgham_ghunnah&gt;سًا و&lt;/tajweed&gt;َأَشَدُّ تَ&lt;tajweed class=ikhafa&gt;نك&lt;/tajweed&gt;ِيلاً &lt;span class=end&gt;٨٤&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 91,
    juzNumber: 5,
  ),
  Verse(
    id: 578,
    verseKey: '4:85',
    text:
        'مّ&lt;tajweed class=idgham_ghunnah&gt;َن ي&lt;/tajweed&gt;َشْفَعْ شَفَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;عَةً حَسَنَ&lt;tajweed class=idgham_ghunnah&gt;ةً ي&lt;/tajweed&gt;َك&lt;tajweed class=idgham_wo_ghunnah&gt;ُن ل&lt;/tajweed&gt;َّهُ&lt;tajweed class=madda_normal&gt;ۥ&lt;/tajweed&gt; نَصِي&lt;tajweed class=idgham_ghunnah&gt;بٌ م&lt;/tajweed&gt;ِّنْهَا‌ۖ وَم&lt;tajweed class=idgham_ghunnah&gt;َن ي&lt;/tajweed&gt;َشْفَعْ شَفَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;عَ&lt;tajweed class=ikhafa&gt;ةً س&lt;/tajweed&gt;َيِّئَ&lt;tajweed class=idgham_ghunnah&gt;ةً ي&lt;/tajweed&gt;َك&lt;tajweed class=idgham_wo_ghunnah&gt;ُن ل&lt;/tajweed&gt;َّهُ&lt;tajweed class=madda_normal&gt;ۥ&lt;/tajweed&gt; كِفْ&lt;tajweed class=idgham_ghunnah&gt;لٌ م&lt;/tajweed&gt;ِّنْهَا‌ۗ وَكَانَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ عَلَىٰ كُلِّ ش&lt;tajweed class=idgham_ghunnah&gt;َىْءٍ م&lt;/tajweed&gt;ُّقِيتًا &lt;span class=end&gt;٨٥&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 91,
    juzNumber: 5,
  ),
  Verse(
    id: 579,
    verseKey: '4:86',
    text:
        'وَإِذَا حُيِّيت&lt;tajweed class=ikhafa_shafawi&gt;ُم ب&lt;/tajweed&gt;ِتَحِيَّ&lt;tajweed class=ikhafa&gt;ةٍ ف&lt;/tajweed&gt;َحَيُّو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; بِأَحْسَنَ مِنْه&lt;tajweed class=madda_obligatory&gt;َآ&lt;/tajweed&gt; أَوْ رُدُّوه&lt;tajweed class=madda_obligatory&gt;َآ‌ۗ&lt;/tajweed&gt; إِ&lt;tajweed class=ghunnah&gt;نّ&lt;/tajweed&gt;َ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا &lt;span class=end&gt;٨٦&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 91,
    juzNumber: 5,
  ),
  Verse(
    id: 580,
    verseKey: '4:87',
    text:
        'ٱللَّهُ ل&lt;tajweed class=madda_obligatory&gt;َآ&lt;/tajweed&gt; إِلَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;هَ إِلَّا هُوَ‌ۚ لَيَ&lt;tajweed class=qalaqah&gt;جْ&lt;/tajweed&gt;مَعَ&lt;tajweed class=ghunnah&gt;نّ&lt;/tajweed&gt;َكُمْ إِلَىٰ يَوْمِ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْقِيَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;مَةِ لَا رَيْبَ فِيهِ‌ۗ وَمَنْ أَصْدَقُ مِنَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهِ حَدِيثًا &lt;span class=end&gt;٨٧&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 92,
    juzNumber: 5,
  ),
  Verse(
    id: 581,
    verseKey: '4:88',
    text:
        '۞ فَمَا لَكُمْ فِى &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْمُنَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;فِقِينَ فِئَتَيْنِ وَ&lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ أَرْكَسَه&lt;tajweed class=ikhafa_shafawi&gt;ُم ب&lt;/tajweed&gt;ِمَا كَسَب&lt;tajweed class=madda_obligatory&gt;ُوٓ&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt;‌ۚ&lt;/tajweed&gt; أَتُرِيدُونَ أَ&lt;tajweed class=ikhafa&gt;ن ت&lt;/tajweed&gt;َهْدُو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; مَنْ أَضَلَّ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ‌ۖ وَم&lt;tajweed class=idgham_ghunnah&gt;َن ي&lt;/tajweed&gt;ُضْلِلِ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ فَلَ&lt;tajweed class=ikhafa&gt;ن ت&lt;/tajweed&gt;َجِدَ لَهُ&lt;tajweed class=madda_normal&gt;ۥ&lt;/tajweed&gt; سَبِيلاً &lt;span class=end&gt;٨٨&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 92,
    juzNumber: 5,
  ),
  Verse(
    id: 582,
    verseKey: '4:89',
    text:
        'وَدُّو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; لَوْ تَكْفُرُونَ كَمَا كَفَرُو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; فَتَكُونُونَ سَو&lt;tajweed class=madda_obligatory&gt;َا&lt;/tajweed&gt;ٓ&lt;tajweed class=ikhafa&gt;ءً‌ۖ ف&lt;/tajweed&gt;َلَا تَتَّخِذُو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; مِنْهُمْ أَوْلِي&lt;tajweed class=madda_obligatory&gt;َا&lt;/tajweed&gt;ٓءَ حَتَّىٰ يُهَاجِرُو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; فِى سَبِيلِ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهِ‌ۚ فَإِ&lt;tajweed class=ikhafa&gt;ن ت&lt;/tajweed&gt;َوَلَّوْ&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; فَخُذُوهُمْ وَ&lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;&lt;tajweed class=qalaqah&gt;قْ&lt;/tajweed&gt;تُلُوهُمْ حَيْثُ وَجَ&lt;tajweed class=idgham_mutajanisayn&gt;د&lt;/tajweed&gt;تُّمُوهُمْ‌ۖ وَلَا تَتَّخِذُو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; مِنْهُمْ وَلِي&lt;tajweed class=idgham_ghunnah&gt;ًّا و&lt;/tajweed&gt;َلَا نَصِيرًا &lt;span class=end&gt;٨٩&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 92,
    juzNumber: 5,
  ),
  Verse(
    id: 583,
    verseKey: '4:90',
    text:
        'إِلَّا &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لَّذِينَ يَصِلُونَ إِلَىٰ قَوْ&lt;tajweed class=iqlab&gt;مِۭ ب&lt;/tajweed&gt;َيْنَكُمْ وَبَيْنَه&lt;tajweed class=idgham_shafawi&gt;ُم م&lt;/tajweed&gt;ِّيثَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;قٌ أَوْ ج&lt;tajweed class=madda_obligatory&gt;َا&lt;/tajweed&gt;ٓءُوكُمْ حَصِرَتْ صُدُورُهُمْ أ&lt;tajweed class=idgham_ghunnah&gt;َن ي&lt;/tajweed&gt;ُقَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;تِلُوكُمْ أَوْ يُقَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;تِلُو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; قَوْمَهُمْ‌ۚ وَلَوْ ش&lt;tajweed class=madda_obligatory&gt;َا&lt;/tajweed&gt;ٓءَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;تَلُوكُمْ‌ۚ فَإِنِ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;عْتَزَلُوكُمْ فَلَمْ يُقَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;تِلُوكُمْ وَأَلْقَوْ&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; إِلَيْكُمُ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;&lt;tajweed class=laam_shamsiyah&gt;ل&lt;/tajweed&gt;سَّلَمَ فَمَا جَعَلَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ لَكُمْ عَلَيْهِمْ سَبِيلاً &lt;span class=end&gt;٩٠&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 92,
    juzNumber: 5,
  ),
  Verse(
    id: 584,
    verseKey: '4:91',
    text:
        'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أ&lt;tajweed class=idgham_ghunnah&gt;َن ي&lt;/tajweed&gt;َأْمَنُوكُمْ وَيَأْمَنُو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; قَوْمَهُمْ كُلَّ مَا رُدّ&lt;tajweed class=madda_obligatory&gt;ُوٓ&lt;/tajweed&gt;&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; إِلَى &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;لْفِتْنَةِ أُرْكِسُو&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; فِيهَا‌ۚ فَإ&lt;tajweed class=idgham_wo_ghunnah&gt;ِن ل&lt;/tajweed&gt;َّمْ يَعْتَزِلُوكُمْ وَيُلْق&lt;tajweed class=madda_obligatory&gt;ُوٓ&lt;/tajweed&gt;&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; إِلَيْكُمُ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;&lt;tajweed class=laam_shamsiyah&gt;ل&lt;/tajweed&gt;سَّلَمَ وَيَكُفّ&lt;tajweed class=madda_obligatory&gt;ُوٓ&lt;/tajweed&gt;&lt;tajweed class=slnt&gt;اْ&lt;/tajweed&gt; أَيْدِيَهُمْ فَخُذُوهُمْ وَ&lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;&lt;tajweed class=qalaqah&gt;قْ&lt;/tajweed&gt;تُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ‌ۚ وَأُ&lt;tajweed class=slnt&gt;وْ&lt;/tajweed&gt;لَ&lt;tajweed class=madda_obligatory&gt;ـٰٓ&lt;/tajweed&gt;ئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;&lt;tajweed class=idgham_ghunnah&gt;نًا م&lt;/tajweed&gt;ُّبِينًا &lt;span class=end&gt;٩١&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 92,
    juzNumber: 5,
  ),
  Verse(
    id: 585,
    verseKey: '4:92',
    text:
        'وَمَا كَانَ لِمُؤْمِنٍ أ&lt;tajweed class=idgham_ghunnah&gt;َن ي&lt;/tajweed&gt;َ&lt;tajweed class=qalaqah&gt;قْ&lt;/tajweed&gt;تُلَ مُؤْمِنًا إِلَّا خَطَـ&lt;tajweed class=idgham_ghunnah&gt;ـًٔا‌ۚ و&lt;/tajweed&gt;َمَ&lt;tajweed class=ikhafa&gt;ن ق&lt;/tajweed&gt;َتَلَ مُؤْمِنًا خَطَـ&lt;tajweed class=ikhafa&gt;ـًٔا ف&lt;/tajweed&gt;َتَحْرِيرُ رَقَبَ&lt;tajweed class=idgham_ghunnah&gt;ةٍ م&lt;/tajweed&gt;ُّؤْمِنَ&lt;tajweed class=idgham_ghunnah&gt;ةٍ و&lt;/tajweed&gt;َدِيَ&lt;tajweed class=idgham_ghunnah&gt;ةٌ م&lt;/tajweed&gt;ُّسَلَّمَةٌ إِلَ&lt;tajweed class=madda_obligatory&gt;ىٰٓ&lt;/tajweed&gt; أَهْلِه&lt;tajweed class=madda_obligatory&gt;ِۦٓ&lt;/tajweed&gt; إِلّ&lt;tajweed class=madda_obligatory&gt;َآ&lt;/tajweed&gt; أ&lt;tajweed class=idgham_ghunnah&gt;َن ي&lt;/tajweed&gt;َصَّدَّقُو&lt;tajweed class=slnt&gt;اْ‌ۚ&lt;/tajweed&gt; فَإِ&lt;tajweed class=ikhafa&gt;ن ك&lt;/tajweed&gt;َانَ مِ&lt;tajweed class=ikhafa&gt;ن ق&lt;/tajweed&gt;َوْمٍ عَدُ&lt;tajweed class=idgham_wo_ghunnah&gt;وٍّ ل&lt;/tajweed&gt;َّكُمْ وَهُوَ مُؤْمِ&lt;tajweed class=ikhafa&gt;نٌ ف&lt;/tajweed&gt;َتَحْرِيرُ رَقَبَ&lt;tajweed class=idgham_ghunnah&gt;ةٍ م&lt;/tajweed&gt;ُّؤْمِنَ&lt;tajweed class=idgham_ghunnah&gt;ةٍ‌ۖ و&lt;/tajweed&gt;َإِ&lt;tajweed class=ikhafa&gt;ن ك&lt;/tajweed&gt;َانَ مِ&lt;tajweed class=ikhafa&gt;ن ق&lt;/tajweed&gt;َوْ&lt;tajweed class=iqlab&gt;مِۭ ب&lt;/tajweed&gt;َيْنَكُمْ وَبَيْنَه&lt;tajweed class=idgham_shafawi&gt;ُم م&lt;/tajweed&gt;ِّيثَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;&lt;tajweed class=ikhafa&gt;قٌ ف&lt;/tajweed&gt;َدِيَ&lt;tajweed class=idgham_ghunnah&gt;ةٌ م&lt;/tajweed&gt;ُّسَلَّمَةٌ إِلَ&lt;tajweed class=madda_obligatory&gt;ىٰٓ&lt;/tajweed&gt; أَهْلِه&lt;tajweed class=madda_normal&gt;ِۦ&lt;/tajweed&gt; وَتَحْرِيرُ رَقَبَ&lt;tajweed class=idgham_ghunnah&gt;ةٍ م&lt;/tajweed&gt;ُّؤْمِنَ&lt;tajweed class=ikhafa&gt;ةٍ‌ۖ ف&lt;/tajweed&gt;َم&lt;tajweed class=idgham_wo_ghunnah&gt;َن ل&lt;/tajweed&gt;َّمْ يَجِ&lt;tajweed class=qalaqah&gt;دْ&lt;/tajweed&gt; فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَ&lt;tajweed class=idgham_ghunnah&gt;ةً م&lt;/tajweed&gt;ِّنَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهِ‌ۗ وَكَانَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ عَلِيمًا حَكِيمًا &lt;span class=end&gt;٩٢&lt;/span&gt;',
    chapterID: 4,
    pageNumber: 93,
    juzNumber: 5,
  ),
  Verse(
    id: 586,
    verseKey: '4:93',
    text:
        'وَم&lt;tajweed class=idgham_ghunnah&gt;َن ي&lt;/tajweed&gt;َ&lt;tajweed class=qalaqah&gt;قْ&lt;/tajweed&gt;تُلْ مُؤْمِ&lt;tajweed class=idgham_ghunnah&gt;نًا م&lt;/tajweed&gt;ُّتَعَ&lt;tajweed class=ghunnah&gt;مّ&lt;/tajweed&gt;ِ&lt;tajweed class=ikhafa&gt;دًا ف&lt;/tajweed&gt;َجَز&lt;tajweed class=madda_obligatory&gt;َا&lt;/tajweed&gt;ٓؤُهُ&lt;tajweed class=madda_normal&gt;ۥ&lt;/tajweed&gt; جَهَ&lt;tajweed class=ghunnah&gt;نّ&lt;/tajweed&gt;َمُ خَ&lt;tajweed class=madda_normal&gt;ـٰ&lt;/tajweed&gt;لِ&lt;tajweed class=ikhafa&gt;دًا ف&lt;/tajweed&gt;ِيهَا وَغَضِبَ &lt;tajweed class=ham_wasl&gt;ٱ&lt;/tajweed&gt;للَّهُ عَلَيْهِ وَلَعَنَهُ&lt;tajweed class=madda_normal&gt;ۥ&lt;/tajweed&gt; وَأَعَدَّ لَهُ&lt;tajweed class=madda_normal&gt;ۥ&lt;/tajweed&gt; عَذَابًا عَظِيمًا &lt;span class=end&gt;٩٣&lt;/span&gt;',
    chapterID: 4,
